typedef struct {int type,mode,timer,refresh,cracked,axis;float target,accel;} ClanItem;
#define CLAN(ip) ((ClanItem*)&(ip)->item_vars)
_Static_assert(sizeof(ClanItem)<=sizeof(((ITStruct*)0)->item_vars),"Clanpot item state fits");
static ITStatusDesc clan_status[6];
static int clan_is(ITStruct *ip){if(!port_remix_enabled()||!main_files[63][7]||ip->kind!=nITKindLinkBomb)return 0;for(int n=1;n<=4;n++)if((void*)ip->attr==(char*)main_files[63][7]+0x40+0x50*(n-1))return n;return 0;}
ITStatusDesc *port_remix_clan_item_status(GObj *g,ITStatusDesc *table){return clan_is(itGetStruct(g))?clan_status:table;}
static void clan_fall(GObj *g){ITStruct *ip=itGetStruct(g);CLAN(ip)->mode=-1;ip->attack_coll.attack_state=nGMAttackStateOff;ip->damage_coll.hitstatus=nGMHitStatusNormal;ip->is_allow_pickup=TRUE;ip->lifetime=780;itMapSetAir(ip);itMainSetStatus(g,clan_status,4);}
static void clan_wait(GObj *g){itMainSetGroundAllowPickup(g);itMainSetStatus(g,clan_status,0);}
static sb32 clan_wait_map(GObj *g){itMapCheckLRWallProcNoFloor(g,clan_fall);return FALSE;}
static sb32 clan_fall_map(GObj *g){return itMapCheckDestroyDropped(g,0.4F,0.3F,clan_wait);}
static sb32 clan_fall_update(GObj *g){ITStruct *ip=itGetStruct(g);itMainApplyGravityClampTVel(ip,1.2F,100);return --ip->lifetime<=0;}
static sb32 clan_hold_update(GObj *g){CLAN(itGetStruct(g))->mode=0;return FALSE;}
static void clan_scale(GObj *g,float n){ITStruct *ip=itGetStruct(g);ip->physics.vel_air.x*=n;ip->physics.vel_air.y*=n;}
static void clan_turn(GObj *g){ITStruct *ip=itGetStruct(g);ClanItem *s=CLAN(ip);s->axis=ip->physics.vel_air.x==0;s->target=-(s->axis?ip->physics.vel_air.y:ip->physics.vel_air.x);s->accel=s->target*0.0546875F;s->mode=2;ip->is_thrown=TRUE;}
